const original = $('Prepare chunk').item.json;

let raw =
  $json.output ??
  $json.text ??
  $json.response ??
  $json.message?.content ??
  '';

if (Array.isArray(raw)) {
  raw = JSON.stringify(raw);
}

raw = String(raw || '').trim();

// вытащить JSON даже если модель вернула текст/markdown
const jsonMatch = raw.match(/\{[\s\S]*\}/);

let parsed = {
  summary: '',
  keywords: [],
  aliases: [],
  topics: []
};

try {
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : raw);
} catch (e) {}

const normalizeArray = (value) => {
  if (!Array.isArray(value)) return [];
  return [...new Set(
    value.map(v => String(v ?? '').trim()).filter(Boolean)
  )];
};

return [
  {
    json: {
      source_document_id: String(original.source_document_id ?? ''),
      source_chunk_id: String(original.source_chunk_id ?? ''),
      chunk_index: Number(original.chunk_index ?? 0),
      content: String(original.content ?? ''),
      metadata: original.metadata ?? {},
      summary: String(parsed.summary ?? '').trim(),
      keywords: normalizeArray(parsed.keywords),
      aliases: normalizeArray(parsed.aliases),
      topics: normalizeArray(parsed.topics)
    }
  }
];

const content = String($json.content ?? '').trim();
const summary = String($json.summary ?? '').trim();
const keywords = Array.isArray($json.keywords) ? $json.keywords : [];
const aliases = Array.isArray($json.aliases) ? $json.aliases : [];
const topics = Array.isArray($json.topics) ? $json.topics : [];

const title = String($json.metadata?.title ?? '').trim();
const url = String($json.metadata?.url ?? '').trim();

const enriched_text = [
  title ? `Title: ${title}` : '',
  url ? `URL: ${url}` : '',
  summary ? `Summary: ${summary}` : '',
  keywords.length ? `Keywords: ${keywords.join(', ')}` : '',
  aliases.length ? `Aliases: ${aliases.join(', ')}` : '',
  topics.length ? `Topics: ${topics.join(', ')}` : '',
  `Content: ${content}`
].filter(Boolean).join('\n\n');

return [
  {
    json: {
      ...$json,
      enriched_text
    }
  }
];

const original = $('Build enriched text').item.json;
const embedding = $json.data?.[0]?.embedding ?? [];

if (!Array.isArray(embedding) || embedding.length !== 1536) {
  return [];
}

return [
  {
    json: {
      source_document_id: original.source_document_id ?? '',
      source_chunk_id: original.source_chunk_id ?? '',
      chunk_index: original.chunk_index ?? 0,
      content: original.content ?? '',
      summary: original.summary ?? '',
      keywords_json: JSON.stringify(original.keywords ?? []),
      aliases_json: JSON.stringify(original.aliases ?? []),
      topics_json: JSON.stringify(original.topics ?? []),
      metadata_json: JSON.stringify(original.metadata ?? {}),
      enriched_text: original.enriched_text ?? '',
      embedding_json: JSON.stringify(embedding)
    }
  }
];

const allItems = $input.all();

const CHUNK_SIZE = 1000;
const CHUNK_OVERLAP = 150;

const out = [];

for (const item of allItems) {
  const content = String(item.json.content ?? '').trim();
  const metadata = item.json.metadata ?? {};
  const source_document_id = String(item.json.id ?? '');

  if (!content) continue;

  let start = 0;
  let chunkIndex = 0;

  while (start < content.length) {
    const end = Math.min(start + CHUNK_SIZE, content.length);
    const chunkText = content.slice(start, end).trim();

    if (chunkText.length > 80) {
      out.push({
        json: {
          source_document_id,
          source_chunk_id: `${source_document_id}::chunk_${String(chunkIndex).padStart(3, '0')}`,
          chunk_index: chunkIndex,
          content: chunkText,
          metadata: {
            ...metadata,
            source_document_id,
            chunk_index: chunkIndex
          }
        }
      });
    }

    if (end >= content.length) break;

    start += CHUNK_SIZE - CHUNK_OVERLAP;
    chunkIndex += 1;
  }
}

return out;

const metadata = $json.metadata ?? {};

return [
  {
    json: {
      source_document_id: String($json.source_document_id ?? ''),
      source_chunk_id: String($json.source_chunk_id ?? ''),
      chunk_index: Number($json.chunk_index ?? 0),
      content: String($json.content ?? ''),
      metadata
    }
  }
];
